-- 97: item search — a kind of item never matches in a category it cannot belong to.
--
-- "khebez" brought back Panadol: the French word for bread, "pain", is a tag of the kind "bread", and the category is called
-- "Pain Relief". The same way a deodorant "coffee", an irrigation "water" pipe, cheese-flavoured chips for "jebne" and chocolate
-- milk for "7alib" were returned as items of the kind. Each kind now carries the categories (shared list, 87: the keys =
-- products.section) it never matches in: every kind of food or drink leaves out the non-food categories, and a few kinds leave
-- out the food categories that only borrow their word as a flavour. An item found by its own NAME is not affected ("pepsi",
-- "panadol"), and a shop's own category is in no list, so it is left alone.
-- The lists are packages/pos-core/src/concepts.ts (NON_FOOD, notIn) — the till's own search uses the same; a test compares them.
--
-- Changed table: match_concepts (+ not_in). Changed function: match_items (three fragments, patched in place). Read-only otherwise.

create table if not exists suqa.match_concepts (
  id          text primary key,
  say         text[]      not null default '{}',   -- how people call the kind
  tags        text[]      not null default '{}',   -- words that mark an item of the kind (name, alias, section)
  not_in      text[]      not null default '{}',   -- 97: category keys whose items are never of this kind
  updated_at  timestamptz not null default now(),
  constraint match_concepts_id_format check (id ~ '^[a-z_]{2,30}$'),
  constraint match_concepts_small check (cardinality(say) <= 60 and cardinality(tags) <= 80)
);
alter table suqa.match_concepts add column if not exists not_in text[] not null default '{}';

