update suqa.match_concepts set not_in = array['Tobacco', 'Vapes', 'Lighters, Gas & Charcoal', 'Argile', 'Argile Tobacco (Maassel)', 'Argile Charcoal', 'Vitamins', 'Pain Relief', 'Hygiene & Sanitizers', 'Skin Care', 'Detergents & Disinfectants', 'Tissues, Wipes & Pads', 'Air Fresheners', 'Insect Control', 'Household', 'Disposable Plates & Cups', 'Candles', 'Shampoo & Conditioner', 'Deodorants', 'Shaving', 'Soap & Hand Wash', 'Toothpaste', 'Toothbrushes', 'Cosmetics & Body Care', 'Hair Colour', 'Batteries', 'Electrical', 'Phones & Accessories', 'Seeds', 'Fertilizers, Pesticides & Soil', 'Irrigation', 'Machines', 'Tools & Spare Parts', 'Tanks, Containers & Shade Nets', 'Beekeeping', 'Pest Control (Public Health)', 'Oils & Lubricants', 'Olive Harvest & Sacks']::text[] where id = 'beer';
