-- the function carries a pg_trgm setting: the library must be loaded in this session before the function is created again (as in 84, 96)
select extensions.similarity('a', 'a');

do $$
declare v_def text := pg_get_functiondef('suqa.match_items(uuid,text[],uuid,int)'::regprocedure);
        v_a text := $q$select s.product_id as pid, s.norm, s.skel, s.name_ar, s.name_en, s.alias_norms, ' ' || s.norm || ' ' || x.sn as txt$q$;
        v_b text := $q$exists (select 1 from hit h where h.no = q.no) as has_kind,$q$;
        v_c text := $q$!~ wk.neg)))) as of_kind$q$;
        n int;
begin
  if position('qy.skip' in v_def) > 0 then return; end if;                                        -- patched already
  foreach v_a in array array[v_a, v_b, v_c] loop
    n := (length(v_def) - length(replace(v_def, v_a, ''))) / length(v_a);
    if n <> 1 then raise exception 'match_items is not as expected (% × "%"): 97 not applied', n, left(v_a, 40); end if;
  end loop;
  v_def := replace(v_def, $q$' ' || s.norm || ' ' || x.sn as txt$q$, $q$' ' || s.norm || ' ' || x.sn as txt, x.sec as sec$q$);
  -- the categories the kinds named in this phrase never match in
  v_def := replace(v_def, v_b, v_b || $q$
           (select array_agg(distinct k) from hit h join suqa.match_concepts c on c.id = h.id cross join lateral unnest(c.not_in) k where h.no = q.no) as skip,$q$);
  v_def := replace(v_def, v_c, $q$!~ wk.neg))) and (qy.skip is null or b.sec <> all(qy.skip))) as of_kind$q$);
  execute v_def;
end $$;
